{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty array")
    if not isinstance(required_symbols, list) or any(not isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be an array of strings")

    required = set(required_symbols)
    by_id = {}
    source_order = []
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        fields = ("id", "parent", "symbol", "depth", "removable", "utility")
        if any(field not in node for field in fields):
            raise ValueError("node is missing a required field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node IDs must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be null or a string")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a nonnegative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)):
            raise ValueError("utility must be numeric")
        if isinstance(utility, float) and not math.isfinite(utility):
            raise ValueError("utility must be finite")
        by_id[node_id] = node
        source_order.append(node_id)

    roots = [node_id for node_id in source_order if by_id[node_id]["parent"] is None]
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root = roots[0]

    children = {node_id: [] for node_id in source_order}
    for node_id in source_order:
        parent = by_id[node_id]["parent"]
        if parent is not None:
            if parent not in by_id or parent == node_id:
                raise ValueError("invalid parent reference")
            if by_id[node_id]["depth"] != by_id[parent]["depth"] + 1:
                raise ValueError("invalid node depth")
            children[parent].append(node_id)
    reachable = set()
    stack = [root]
    while stack:
        node_id = stack.pop()
        if node_id in reachable:
            raise ValueError("cyclic tree")
        reachable.add(node_id)
        stack.extend(reversed(children[node_id]))
    if reachable != set(source_order):
        raise ValueError("tree must be connected")

    retained = set(source_order)
    removal_order = []
    candidates = sorted(
        (node_id for node_id in source_order if by_id[node_id]["removable"]),
        key=lambda node_id: (-by_id[node_id]["depth"], node_id),
    )
    for node_id in candidates:
        node = by_id[node_id]
        if node_id == root or node["symbol"] in required or node_id not in retained:
            continue
        if any(child in retained for child in children[node_id]):
            continue
        trial = retained - {node_id}
        if any(not any(by_id[other]["symbol"] == symbol for other in trial) for symbol in required):
            continue
        retained.remove(node_id)
        removal_order.append(node_id)

    return {
        "removed_node_ids": removal_order,
        "retained_node_ids": sorted(retained),
    }
